const vt = items[0].json;
const abuse = items[1].json;
const otx = items[2].json;

return [{
  json: {
    ioc_value: $('Webhook Trigger').first().json.value,
    virustotal: {
      malicious: vt?.data?.attributes?.last_analysis_stats?.malicious || 0,
      suspicious: vt?.data?.attributes?.last_analysis_stats?.suspicious || 0
    },
    abuseipdb: {
      score: abuse?.data?.abuseConfidenceScore || 0,
      reports: abuse?.data?.totalReports || 0,
      country: abuse?.data?.countryCode || 'unknown'
    },
    otx: {
      pulses: otx?.pulse_info?.count || 0
    },
    risk_level: calculateRisk(vt, abuse, otx)
  }
}];

function calculateRisk(vt, abuse, otx) {
  const vtScore = vt?.data?.attributes?.last_analysis_stats?.malicious || 0;
  const abuseScore = abuse?.data?.abuseConfidenceScore || 0;
  if (vtScore > 5 || abuseScore > 80) return 'critical';
  if (vtScore > 2 || abuseScore > 50) return 'high';
  if (vtScore > 0 || abuseScore > 20) return 'medium';
  return 'low';
}

